import{_ as a,o as r,c as t,a6 as i}from"./chunks/framework.CDz9-eKs.js";const f=JSON.parse('{"title":"Driver selection","description":"","frontmatter":{},"headers":[],"relativePath":"background/drivers.md","filePath":"background/drivers.md","lastUpdated":null}'),n={name:"background/drivers.md"};function s(o,e,c,d,l,v){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="Driver-selection" tabindex="-1">Driver selection <a class="header-anchor" href="#Driver-selection" aria-label="Permalink to &quot;Driver selection {#Driver-selection}&quot;">​</a></h1><p>GeoDataFrames selects an I/O driver from a filename extension. Importing a native format package activates its extension, so the same <code>read</code> or <code>write</code> call can dispatch to that package&#39;s native implementation in the current session. Without an active native extension, automatic selection uses ArchGDAL.</p><p><code>ArchGDALDriver()</code> remains available as an explicit fallback. Select it when a native extension is unavailable or when an ArchGDAL/GDAL workflow is required, even if a native package has been imported.</p><p>Each native package owns its read and write interface. Its keyword arguments may differ in name, meaning, and availability from ArchGDAL&#39;s and from those of other native packages. GeoDataFrames therefore delegates those keywords rather than presenting an unsafe unified keyword vocabulary.</p><p>For the selection procedure, see <a href="./../how-to/use-native-drivers">use a native driver</a>. The <a href="./../reference/native-drivers">native-driver reference</a> lists available extensions, and the <a href="./../reference/archgdal">ArchGDAL reference</a> describes the fallback driver.</p>',5)])])}const p=a(n,[["render",s]]);export{f as __pageData,p as default};
